import React from "react"
import ProgressBar from "react-bootstrap/ProgressBar"
import { RiFlutterFill } from "react-icons/ri"
import { SiFirebase, SiGooglecloud, SiDocker, SiPython, SiReact, SiCircleci } from "react-icons/si"
import Fadeup from "./Fadeup"

function Skills(){
    return(
        <section id = "skills" style= {{paddingBottom: "10%", paddingTop: "5%"}}>
        <div>
        <header className="head-style">Skills</header>
        <br /> <br /> 
        <Fadeup>
        <p className= "texted-style">
        <RiFlutterFill /> &nbsp;
            Flutter 
            <p />
            <ProgressBar now={90} />
        </p>
        <p className= "texted-style">
        <SiFirebase /> &nbsp;
            Firebase 
            <p />
            <ProgressBar now={75} />
        </p>
        <p className= "texted-style">
        <SiPython /> &nbsp;
            Python
            <p />
            <ProgressBar now={50} />
        </p>
        <p className= "texted-style">
        <SiGooglecloud /> &nbsp;
            Google Cloud Platform
            <p />
            <ProgressBar now={60} />
        </p>
        <p className= "texted-style">
        <SiDocker /> &nbsp;
            Docker
            <p />
            <ProgressBar now={65} />
        </p>
        <p className= "texted-style">
        <SiReact /> &nbsp;
            ReactJS
            <p />
            <ProgressBar now={60} />
        </p>
        <p className= "texted-style">
        <SiCircleci /> &nbsp;
            CI/CD
            <p />
            <ProgressBar now={80} />
        </p>
        </Fadeup>
        
        </div>
        </section>
    );
}

export default Skills;