import React from "react";
import { Navbar } from "react-bootstrap";
import Nav from "react-bootstrap/Nav";
import "bootstrap/dist/css/bootstrap.min.css";
import "../fonts.css";
import logo from "../assets/logo.png";
import resume from "../assets/resume.pdf";
import {
  AiFillGithub,
  AiFillLinkedin,
  AiFillFacebook,
  AiOutlineTwitter,
} from "react-icons/ai";
import { FaDev } from "react-icons/fa";
import ScrollIntoView from "react-scroll-into-view";

class AppBar extends React.Component {
  constructor(props) {
    super(props);
    this.state = { isTop: true };
  }
  handleScroll = (e) => {
    const isTop = window.scrollY < 100;

    if (isTop !== this.state.isTop) {
      this.setState({ isTop });
    }
  };

  componentDidMount() {
    window.addEventListener("scroll", this.handleScroll);
  }

  componentWillUnmount() {
    window.addEventListener("scroll", this.handleScroll);
  }

  render() {
    return (
      <header>
        <Navbar
          fixed="top"
          expand="lg"
          collapseOnSelect="true"
          className={this.state.isTop ? "default" : "sticky"}
          variant="color-nav"
        >
          <ScrollIntoView selector="body">
            <Navbar.Brand>
              <img
                src={logo}
                className={`d-inline-block align-top ${
                  this.state.isTop ? "logo-default" : "logo-sticky"
                }`}
                alt="Amey Sunu Logo"
              />
            </Navbar.Brand>
          </ScrollIntoView>
          <Navbar.Toggle
            aria-controls="basic-navbar-nav"
            className="navbar-dark bg-dark"
          />
          <Navbar.Collapse id="basic-navbar-nav">
            <Nav className="ml-auto navbar-items">
              <ScrollIntoView selector="#about">
                <Nav.Link style={{ padding: "10px" }} className="section-link">
                  About
                </Nav.Link>
              </ScrollIntoView>
              {/* <ScrollIntoView selector="#projects">
                <Nav.Link style={{ padding: "10px" }} className="section-link">
                  Projects
                </Nav.Link>
              </ScrollIntoView> */}
              <ScrollIntoView selector="#skills">
                <Nav.Link style={{ padding: "10px" }} className="section-link">
                  Skills
                </Nav.Link>
              </ScrollIntoView>
              <ScrollIntoView selector="#contact">
                <Nav.Link style={{ padding: "10px" }} className="section-link">
                  Contact
                </Nav.Link>
              </ScrollIntoView>
              <ScrollIntoView selector="">
                <Nav.Link
                  style={{ padding: "10px" }}
                  className="section-link"
                  a
                  href="http://ameyblog.co/"
                >
                  Blog
                </Nav.Link>
              </ScrollIntoView>
              <ScrollIntoView selector="">
                <Nav.Link
                  style={{ padding: "10px" , color: "#007BFF"}}
                  className="section-link"
                  a
                  href={resume}
                >
                  My Resume
                </Nav.Link>
              </ScrollIntoView>
            </Nav>
          </Navbar.Collapse>
        </Navbar>
        <ul className="no-bullets">
          <li className="iconsize">
            <a href="https://github.com/ameysunu">
              <AiFillGithub className="icons" />
            </a>
          </li>
          <li className="iconsize">
            <a href="https://www.linkedin.com/in/amey-sunu-187103171/">
              <AiFillLinkedin className="icons" />
            </a>
          </li>
          <li className="iconsize">
            <a href="https://www.twitter.com/ameysunu">
              <AiOutlineTwitter className="icons" />
            </a>
          </li>
          <li className="iconsize">
            <a href="https://www.facebook.com/ameysunu.sunu/">
              <AiFillFacebook className="icons" />
            </a>
          </li>
          <li className="iconsize">
            <a href="https://dev.to/ameysunu">
              <FaDev className="icons" />
            </a>
          </li>
        </ul>
      </header>
    );
  }
}

export default AppBar;
